def fill_frames(grid):
    g=[r[:] for r in grid]; H,W=len(g),len(g[0])
    from collections import Counter, deque
    cnt=Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if seen[i][j] or g[i][j]==bg: continue
            color=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; comp=[]
            while q:
                a,b=q.popleft(); comp.append((a,b))
                for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+da,b+db
                    if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==color:
                        seen[x][y]=True; q.append((x,y))
            rs=[c[0] for c in comp]; cs=[c[1] for c in comp]
            t,b_,l,r=min(rs),max(rs),min(cs),max(cs)
            if len(comp)!=(b_-t+1)*(r-l+1): continue  # not a filled bbox -> not frame
            ok=all(g[x][y]==color for x in range(t,b_+1) for y in range(l,r+1) if x in(t,b_) or y in(l,r))
            if not ok: continue
            fill=7 if (r-l-1)%2==1 else 2
            for x in range(t+1,b_):
                for y in range(l+1,r):
                    if g[x][y]==bg: g[x][y]=fill
    return g

